SELECT facet, f0, f1, f2, f3, f4, f5, f6, at, verdict, verifier, place, verifiers, sum(n) AS n FROM (SELECT facet, f0, f1, f2, f3, f4, f5, f6, at, CASE WHEN facet = 7 THEN verdict_series END AS verdict, CASE WHEN facet = 8 AND place <= 3 THEN verifier END AS verifier, CASE WHEN facet = 8 AND place <= 3 THEN place END AS place, CASE WHEN facet = 8 THEN verifiers END AS verifiers, n FROM (SELECT facet, f0, f1, f2, f3, f4, f5, f6, at, verdict_series, verifier, n, rank, place, max(place) OVER (PARTITION BY facet) AS verifiers FROM (SELECT facet, f0, f1, f2, f3, f4, f5, f6, at, verdict_series, verifier, n, rank, dense_rank() OVER (PARTITION BY facet ORDER BY total DESC, verifier) AS place FROM (SELECT facet, f0, f1, f2, f3, f4, f5, f6, at, verdict_series, verifier, n, row_number() OVER (PARTITION BY facet ORDER BY n DESC, f0, f1, f2, f3, f4, f5, f6) AS rank, sum(n) OVER (PARTITION BY facet, verifier) AS total FROM (SELECT CASE WHEN grouping(verdict_series) = 0 THEN 7 WHEN grouping(verifier) = 0 THEN 8 WHEN grouping(status) = 0 THEN 0 WHEN grouping(verdict) = 0 THEN 1 WHEN grouping(verifier_card_uid) = 0 THEN 2 WHEN grouping(service_name) = 0 THEN 3 WHEN grouping(subject_name) = 0 THEN 4 WHEN grouping(run_id) = 0 THEN 5 ELSE 6 END AS facet, status AS f0, verdict AS f1, verifier_card_uid AS f2, service_name AS f3, subject_name AS f4, run_id AS f5, group_id AS f6, at, verdict_series, verifier, count(*) AS n FROM (SELECT status, verdict, verifier_card_uid, service_name, subject_name, run_id, group_id, date_bin($3::interval, recorded_at) AS at, coalesce(verdict, 'no verdict') AS verdict_series, verifier_card_uid AS verifier FROM (SELECT i.execution_id, i.recorded_at, i.verifier_card_uid, i.binding_id, i.group_id, i.origin, i.run_id, i.subject_kind, i.subject_name, i.subject_version, i.subject_card_uid, i.workload_card_uid, i.service_name, i.service_version, i.deployment_environment, r.result_id, r.verdict, r.ended_at, CASE WHEN i.origin = 'direct' THEN CASE WHEN r.result_id IS NOT NULL THEN 'completed' ELSE 'not recorded' END ELSE coalesce(q.status, 'pending') END AS status FROM bifrost.verification.execution_inputs i LEFT JOIN (SELECT execution_id, last_value(status ORDER BY occurred_at, event_id) AS status FROM bifrost.verification.execution_events WHERE event = 'status' AND occurred_at >= $1::timestamptz - INTERVAL '1 hour' GROUP BY execution_id) q ON q.execution_id = i.execution_id LEFT JOIN (SELECT e.execution_id, e.value -> 'terminal' ->> 'result_id' AS result_id FROM bifrost.verification.execution_events e JOIN (SELECT execution_id, max(sequence) AS sequence FROM bifrost.verification.execution_events WHERE event = 'checkpoint' AND occurred_at >= $1::timestamptz - INTERVAL '1 hour' GROUP BY execution_id) l ON l.execution_id = e.execution_id AND l.sequence = e.sequence WHERE e.event = 'checkpoint' AND e.occurred_at >= $1::timestamptz - INTERVAL '1 hour') s ON s.execution_id = i.execution_id LEFT JOIN bifrost.verification.results r ON r.execution_id = i.execution_id AND r.ended_at >= $1::timestamptz - INTERVAL '1 hour' AND (i.origin = 'direct' OR r.result_id = s.result_id)) AS executions WHERE recorded_at >= $1::timestamptz AND recorded_at < $2::timestamptz) AS population GROUP BY GROUPING SETS ((status), (verdict), (verifier_card_uid), (service_name), (subject_name), (run_id), (group_id), (at, verdict_series), (at, verifier))) AS grouped) AS ranked) AS placed) AS counted WHERE facet >= 7 OR rank <= 11) AS kept GROUP BY facet, f0, f1, f2, f3, f4, f5, f6, at, verdict, verifier, place, verifiers ORDER BY facet, at, n DESC, f0, f1, f2, f3, f4, f5, f6, place